INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1101, 'Genesis 38:23', 'Genesis', 38, 23, '&nbsp;يهوداه ووئيل، ”پرېږده چې هغه څيزونه هغه د ځان سره وساتى. مونږ نۀ غواړُو چې خلق راپورې وخاندى. ما هغې له د مزدورۍ ورکولو کوشش وکړو، خو تا هغه ونۀ موندله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1102, 'Genesis 38:24', 'Genesis', 38, 24, '&nbsp;تقريباً درې مياشتې وروستو يهوداه ته چا ووئيل، ”ستا اِنږور تامار کنجرتوب کولو او اوس هغه اُميدواره ده.“ يهوداه ووئيل، ”هغه بهر راوباسئ او په اور کښې يې وسوزوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1103, 'Genesis 38:25', 'Genesis', 38, 25, '&nbsp;چې هغه بهر راوويستلے شوه، هغې خپل سخر له خبر ورولېږلو، ”زۀ د هغه سړى نه اُميدواره يم چې دا څيزونه د چا وى. دې ته وګورئ چې دا مهر سره د مزى او دا لښته د چا دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1104, 'Genesis 38:26', 'Genesis', 38, 26, '&nbsp;يهوداه دا وپېژندل او وې وئيل، ”هغه په حقه ده. زۀ د هغې سره په خپله ذمه وارۍ کښې ناکام شوے يم. ځکه چې ما هغه خپل زوئ سيله ته وادۀ نۀ کړه.“ او يهوداه د هغې سره بيا شپه تېره نۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1105, 'Genesis 38:27', 'Genesis', 38, 27, '&nbsp;چې کله د هغې د بچى پېدا کېدو وخت راغلو، دا پته ولګېده چې د هغې جوړه بچى پېدا کېدونکى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1106, 'Genesis 38:28', 'Genesis', 38, 28, '&nbsp;چې کله هغه په تکليف کښې وه، يو ماشوم لاس رابهر کړو، دايڼې يې لاس راونيولو، سور تار يې ترې تاو کړو او وې وئيل، ”دا وړومبے پېدا شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1107, 'Genesis 38:29', 'Genesis', 38, 29, '&nbsp;خو هغۀ خپل لاس واپس راښکلو او د هغۀ ورور وړومبے پېدا شو. بيا هغه دايڼې ووئيل، ”تا څنګه د ځان دپاره د راوتلو لار جوړه کړې ده.“ نو د هغۀ نوم فارص شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1108, 'Genesis 38:30', 'Genesis', 38, 30, '&nbsp;بيا د هغۀ ورور پېدا شو چې د هغۀ د لاس نه سور تار تاو وو او د هغۀ نوم زارح شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1109, 'Genesis 39:1', 'Genesis', 39, 1, '&nbsp;کله چې اِسمٰعيليانو يوسف مِصر ته بوتلو، هغه يې فوطيفار نومې د فِرعون په يو آفسر باندې خرڅ کړو، چې هغه د محل د څوکيدارانو مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1110, 'Genesis 39:2', 'Genesis', 39, 2, '&nbsp;مالِک خُدائ د يوسف مل وو او هغه يې کامياب کړو. هغه د خپل مِصرى نېک په کور کښې اوسېدو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1111, 'Genesis 39:3', 'Genesis', 39, 3, '&nbsp;چې هغۀ وليدل چې مالِک خُدائ د يوسف مل دے او هغه يې په هر کار کښې کامياب کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1112, 'Genesis 39:4', 'Genesis', 39, 4, '&nbsp;نو فوطيفار د هغۀ نه خوشحال وو او هغه يې خپل ذاتى خِدمتګار او د خپل کور مشر يې جوړ کړو او خپل هر څۀ يې هغۀ ته وسپارل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1113, 'Genesis 39:5', 'Genesis', 39, 5, '&nbsp;هم د هغه وخت نه، هم د يوسف په وجه مالِک خُدائ د دې مِصرى خاندان له برکت ورکړے وو او ورسره هغه هر څيز له يې برکت ورکړو چې د هغۀ په کور او په پټو کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1114, 'Genesis 39:6', 'Genesis', 39, 6, '&nbsp;فوطيفار چې څۀ هم لرل هغه يې يوسف له ورکړل چې خيال يې ساتى او په خپله يې د خوراک نه بغېر د يو څيز فکر هم نۀ کولو. نو يوسف ښائسته بدن لرلو او ښُکلےځوان وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1115, 'Genesis 39:7', 'Genesis', 39, 7, '&nbsp;او څۀ موده وروستو د هغۀ د نېک ښځې يوسف ته د شوق په سترګه کتل او ورته يې ووئيل، ”راشه او ما سره څمله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1116, 'Genesis 39:8', 'Genesis', 39, 8, '&nbsp;هغۀ اِنکار وکړو او ورته يې ووئيل، ”ګوره، زما نېک په خپله په دې کور کښې د يو څيز فکر هم نۀ کوى، ځکه چې زۀ دلته يم. هغۀ زۀ په خپل هر څيز مشر جوړ کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1117, 'Genesis 39:9', 'Genesis', 39, 9, '&nbsp;زۀ په دې کور کښې د هغۀ هومره اختيار لرم او هغۀ ستا نه بغېر زما نه هيڅ څيز هم نۀ دے منع کړے. نو بيا زۀ داسې غلط کار څنګه وکړم چې د خُدائ پاک ګناهګار شم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1118, 'Genesis 39:10', 'Genesis', 39, 10, '&nbsp;اګر چې هغې به هره ورځ يوسف ته وئيل، خو هغۀ د هغې خبره نۀ منله چې ورسره څملى او نۀ ورنزدې کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1119, 'Genesis 39:11', 'Genesis', 39, 11, '&nbsp;خو يوه ورځ چې کله يوسف د کار دپاره کور ته ننوتو، په کور کښې يو خِدمتګار هم نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1120, 'Genesis 39:12', 'Genesis', 39, 12, '&nbsp;هغې هغه د قميص نه ونيوو او ورته يې ووئيل، ”راشه. ما سره څمله.“ خو هغۀ بهر منډه کړه او وتښتېدو او د هغۀ قميص د هغې په لاس کښې پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1121, 'Genesis 39:13', 'Genesis', 39, 13, '&nbsp;کله چې هغې وليدل چې د هغۀ نه قميص پاتې شو او د کور نه يې بهر منډه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1122, 'Genesis 39:14', 'Genesis', 39, 14, '&nbsp;هغې د کور خِدمتګاران راوغوښتل او وې وئيل، ”دا وګورئ، زما خاوند چې کور ته کوم عبرانے راوستے دے هغه مونږ شرموى. هغه زما کوټې ته راننوتو او ما ته يې د لاس راچولو کوشش وکړو، خو ما په زوره زوره چغې ووهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1123, 'Genesis 39:15', 'Genesis', 39, 15, '&nbsp;نو زما چغو سره هغۀ بهر منډه کړه او قميص يې زما سره پرېښودو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1124, 'Genesis 39:16', 'Genesis', 39, 16, '&nbsp;هغې دا قميص د يوسف د نېک کور ته راتلو پورې وساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1125, 'Genesis 39:17', 'Genesis', 39, 17, '&nbsp;بيا هغې هغۀ ته هم هغه شان قيصه تېره کړه، ”تا چې کوم عبرانے نوکر دلته راوستلے دے هغه زما کوټې ته راننوتو او لاس يې راواچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1126, 'Genesis 39:18', 'Genesis', 39, 18, '&nbsp;خو چې کله ما چغې ووهلې، هغۀ بهر منډه کړه او خپل قميص يې زما سره پرېښودو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1127, 'Genesis 39:19', 'Genesis', 39, 19, '&nbsp;چې کله د يوسف نېک دا قيصه واورېده کومه چې خپلې ښځې ورته بيان کړه، نو هغه د غصې نه تک سور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1128, 'Genesis 39:20', 'Genesis', 39, 20, '&nbsp;نو يوسف يې ونيولو او په هغه قېدخانه کښې يې بند کړو چرته به چې د بادشاه قېديان قېد کولے شول او هغه هلته په قېدخانه کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1129, 'Genesis 39:21', 'Genesis', 39, 21, '&nbsp;خو مالِک خُدائ د يوسف مل وو نو رحم يې پرې وکړو او هغه د قېدخانې د آفسر په نظر کښې ښۀ راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1130, 'Genesis 39:22', 'Genesis', 39, 22, '&nbsp;هغۀ يوسف د نورو ټولو قېديانو مشر جوړ کړو او چې په قېدخانه کښې څۀ هم کېدل د هر څۀ ذمه وارى يې ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1131, 'Genesis 39:23', 'Genesis', 39, 23, '&nbsp;د قېدخانې آفسر د هغه يو څيز فکر هم نۀ کولو چې يوسف له يې کومه ذمه وارى ورکړې وه، ځکه چې مالِک خُدائ د يوسف مل وو او هغه يې په هر کار کښې کامياب کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1132, 'Genesis 40:1', 'Genesis', 40, 1, '&nbsp;څۀ موده وروستو د مِصر د بادشاه ساقى او مشر نانبائى داسې څۀ غلط کار وکړو چې بادشاه ورباندې خفه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1133, 'Genesis 40:2', 'Genesis', 40, 2, '&nbsp;فِرعون دې دواړو آفسرانو ته سخت غصه شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1134, 'Genesis 40:3', 'Genesis', 40, 3, '&nbsp;او دوئ يې د څوکيدارانو د مشر په کور کښې قېد کړل، هم په هغه ځائ کښې چې چرته يوسف هم قېد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1135, 'Genesis 40:4', 'Genesis', 40, 4, '&nbsp;دوئ ډېر وخت په قېدخانه کښې تېر کړو او د څوکيدارانو مشر يوسف ته يې حواله کړل چې د دوئ خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1136, 'Genesis 40:5', 'Genesis', 40, 5, '&nbsp;يوه شپه په قېدخانه کښې د مِصر د بادشاه ساقى او مشر نانبائى دواړو خوب وليدو او د هر يو خوب خپل خپل مطلب وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1137, 'Genesis 40:6', 'Genesis', 40, 6, '&nbsp;چې کله يوسف هغوئ له سحر ورَغلو، هغۀ دوئ پرېشانه وليدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1138, 'Genesis 40:7', 'Genesis', 40, 7, '&nbsp;هغۀ د هغوئ نه تپوس وکړو، ”تاسو ولې نن دومره پرېشانه ښکارئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1139, 'Genesis 40:8', 'Genesis', 40, 8, '&nbsp;هغوئ ورته ووئيل، ”مونږ دواړو يو يو خوب ليدلے دے او دلته داسې هيڅ څوک هم نشته چې تعبير يې وکړى.“ يوسف ورته ووئيل چې، ”دا خو خُدائ پاک دے چې هغه د خوبونو د تعبير عِلم ورکوى، تاسو ما ته خپل خوبونه ووايئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1140, 'Genesis 40:9', 'Genesis', 40, 9, '&nbsp;نو ساقى ووئيل، ”زما په خوب کښې زما په مخکښې د انګورو بوټے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1141, 'Genesis 40:10', 'Genesis', 40, 10, '&nbsp;د دې درې څانګې وې. چې څنګه د دې نه پاڼې راووتلې، غوټۍ راڅرګندې شوې او انګور پاخۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1142, 'Genesis 40:11', 'Genesis', 40, 11, '&nbsp;ما د فِرعون پيالۍ په لاس کښې نيولې وه، نو ما انګور راواخستل او دا مې په پيالۍ کښې نچوړ کړل او هغۀ له مې ورکړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1143, 'Genesis 40:12', 'Genesis', 40, 12, '&nbsp;يوسف ووئيل، ”د دې تعبير دا دے، دا درې څانګې درې ورځې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1144, 'Genesis 40:13', 'Genesis', 40, 13, '&nbsp;په دې درېو ورځو کښې به فِرعون تا آزاد کړى او په خپل ځائ به دې کښېنوى. تۀ به هغۀ له پيالۍ ورکړې او د مخکښې په شان به د هغۀ ساقى يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1145, 'Genesis 40:14', 'Genesis', 40, 14, '&nbsp;خو چې کله ستا دپاره هر څۀ سم شى نو ما مۀ هېروه او په ما ډېره مِهربانى وکړه فِرعون ته زما ذِکر وکړه او د دې قېدخانې نه خلاصېدلو کښې زما مدد وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1146, 'Genesis 40:15', 'Genesis', 40, 15, '&nbsp;ځکه چې زۀ د عبرانيانو د مُلک نه راتښتولے شوے وم او ما دلته په مِصر کښې داسې هيڅ کار نۀ دے کړے چې په دې قېدخانه کښې بندى شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1147, 'Genesis 40:16', 'Genesis', 40, 16, '&nbsp;چې کله مشر نانبائى پوهه شو چې د ساقى د خوب تعبير ښۀ وو، هغۀ هم يوسف ته ووئيل، ”ما هم خوب ليدلے دے، ما په سر د روټۍ درې ټوکرۍ روانې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1148, 'Genesis 40:17', 'Genesis', 40, 17, '&nbsp;د ټولو سر ته ټوکرۍ کښې د فِرعون دپاره هر قِسم روټۍ وې او مارغانو دا خوړلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1149, 'Genesis 40:18', 'Genesis', 40, 18, '&nbsp;يوسف جواب ورکړو، ”د دې تعبير دا دے. هغه درې ټوکرۍ درې ورځې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1150, 'Genesis 40:19', 'Genesis', 40, 19, '&nbsp;په درېو ورځو کښې به فِرعون ستا نه سر قلم کړى. بيا به تا په يوه ونه کښې راځوړند کړى او مارغان به ستا غوښه وخورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1151, 'Genesis 40:20', 'Genesis', 40, 20, '&nbsp;په درېمه ورځ دا د فِرعون د پېدايښت ورځ وه، هغۀ خپلو ټولو درباريانو له يوه لويه روټۍ وکړه، هغۀ خپل ساقى او مشر نانبائى رابهر کړل او د خپلو درباريانو په مخکښې يې حاضر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1152, 'Genesis 40:21', 'Genesis', 40, 21, '&nbsp;فِرعون، ساقى بيا په خپل وړومبى ځائ کښېنولو او ساقى پيالۍ فِرعون له په لاس کښې ورکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1153, 'Genesis 40:22', 'Genesis', 40, 22, '&nbsp;خو هغه مشر نانبائى يې راځوړند کړو. دا ټول هم هغه شان وشول لکه څنګه چې يوسف فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1154, 'Genesis 40:23', 'Genesis', 40, 23, '&nbsp;خو ساقى يوسف راياد نۀ کړو. او هېر يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1155, 'Genesis 41:1', 'Genesis', 41, 1, '&nbsp;پوره دوه کاله تېر شوى وُو چې د مِصر فِرعون خوب وليدو چې هغه د نيل درياب په غاړه ولاړ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
