(1162, 'Genesis 41:8', 'Genesis', 41, 8, '&nbsp;سحر هغه پرېشان وو، نو هغۀ د مِصر ټول نجوميان او هوښيار خلق راوغوښتل. هغۀ ورته خپل خوبونه ووئيل، خو هيچا هم هغۀ ته د دې تعبير نۀ شو ښودلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1163, 'Genesis 41:9', 'Genesis', 41, 9, '&nbsp;بيا ساقى فِرعون ته ووئيل، ”صاحِبه، نن زۀ دا خبره څرګندوم چې زما نه غلطى شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
