(1191, 'Genesis 41:37', 'Genesis', 41, 37, '&nbsp;د فِرعون او د هغۀ د درباريانو په نظر کښې دا منصوبه ښۀ راغله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
